import{_ as s,C as i,o as n,c as o,j as a,a as r,E as l,a6 as d}from"./chunks/framework.DIp0zHSV.js";const h="/dev/releases/2026.06.01.1/card-picker-suggestions.webp",y=JSON.parse('{"title":"LCARdS 2026.06.01.1","description":"state_attribute colours, colour templates, HA 2026.6 compatibility and card picker suggestions.","frontmatter":{"version":"2026.06.01.1","date":"2026-06-01T00:00:00.000Z","status":"released","summary":"state_attribute colours, colour templates, HA 2026.6 compatibility and card picker suggestions.","breaking":false},"headers":[],"relativePath":"releases/2026.06.01.1.md","filePath":"releases/2026.06.01.1.md","lastUpdated":1791928403000}'),c={name:"releases/2026.06.01.1.md"};function p(k,e,u,g,E,b){const t=i("ReleaseMeta");return n(),o("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-06-01-1",tabindex:"-1"},[r("LCARdS 2026.06.01.1 "),a("a",{class:"header-anchor",href:"#lcards-2026-06-01-1","aria-label":'Permalink to "LCARdS 2026.06.01.1"'},"​")],-1)),l(t),e[1]||(e[1]=d(`<p>A bit of a smaller release with respect to new features - only a couple new items.<br> However, the release has large and important updates for HA 2026.5+ to keep in line with HA UI deprecated elements and changes.</p><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h3 id="state-based-colour-config-enhancements" tabindex="-1">State-Based Colour Config Enhancements <a class="header-anchor" href="#state-based-colour-config-enhancements" aria-label="Permalink to &quot;State-Based Colour Config Enhancements&quot;">​</a></h3><h4 id="attribute-support-state-attribute" tabindex="-1">Attribute Support <a href="/dev/core/colours.html#exact-match-keys-from-an-attribute-state-attribute">(<code>state_attribute</code>)</a> <a class="header-anchor" href="#attribute-support-state-attribute" aria-label="Permalink to &quot;Attribute Support [(\`state_attribute\`)](/core/colours#exact-match-keys-from-an-attribute-state-attribute)&quot;">​</a></h4><p>Button, Elbow, and Slider cards now support a top-level <code>state_attribute</code> config field. <br> When set, the resolved string value of that attribute becomes the <strong>highest-priority key</strong> for all exact-match state-based colour lookups across the card.</p><p>Useful for for entities such as <code>climate</code> where the desired signal is an attribute like <code>hvac_action</code> rather than the top-level state (<code>heat</code>/<code>cool</code>)</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:lcards-button</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">preset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lozenge</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">climate.living_room</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">state_attribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hvac_action</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # &quot;heating&quot;, &quot;cooling&quot;, &quot;idle&quot;, &quot;off&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">icon_style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    heating</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;var(--lcards-orange)&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cooling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;var(--lcards-blue)&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    idle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;var(--lcards-gray)&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;off&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;var(--lcards-gray-dark)&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">icon_area_background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  heating</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alpha(var(--lcards-orange), 0.15)&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cooling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alpha(var(--lcards-blue), 0.15)&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  idle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">transparent</span></span></code></pre></div><p><code>state_attribute</code> applies to every state-based colour config on the card like backgrounds, icons, borders, etc.<br> Attribute values are serialized to strings so boolean attributes can be matched with <code>&quot;true&quot;</code> / <code>&quot;false&quot;</code>, which you write as-is in your YAML keys.</p><p><code>state_attribute</code> does not replace <code>ranges_attribute</code>. The two work independently:</p><table tabindex="0"><thead><tr><th>Config field</th><th>What it controls</th></tr></thead><tbody><tr><td><code>state_attribute</code></td><td>Which attribute value is matched against exact string keys (<code>heating</code>, <code>true</code>, <code>fade</code>, …)</td></tr><tr><td><code>ranges_attribute</code></td><td>Which attribute&#39;s numeric value is used for range keys (<code>above:50</code>, <code>between:10:90</code>, …)</td></tr></tbody></table><hr><h4 id="colour-config-object-as-a-template" tabindex="-1">Colour Config Object as a <a href="/dev/core/colours.html#template-strings-as-colour-values">Template</a> <a class="header-anchor" href="#colour-config-object-as-a-template" aria-label="Permalink to &quot;Colour Config Object as a [Template](/core/colours#template-strings-as-colour-values)&quot;">​</a></h4><p>Instead of defining per-state colours, the <code>.color</code> config fields (ie. <code>icon_style.color</code>, <code>icon_area_background</code>, <code>background</code>, <code>border</code> color, etc.) can now be set to a <strong>single template string</strong> for the whole object. The template must evaluate to a single colour value (in any supported format.) This allows for specific advanced logic where needed.</p><p>Previously, using a template at the field level was broken: the raw template string was passed through unresolved. It is now evaluated via the card&#39;s pre-evaluated style cache before the colour is applied.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:lcards-button</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">preset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lozenge</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">climate.living_room</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">icon_style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{ state_attr(&#39;climate.living_room&#39;, &#39;hvac_action&#39;) | default(&#39;off&#39;) }}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">icon_area_background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{ &#39;#ff6600&#39; if is_state(&#39;climate.living_room&#39;, &#39;heat&#39;) else &#39;#444444&#39; }}&quot;</span></span></code></pre></div><h2 id="enhancements-fixes" tabindex="-1">Enhancements &amp; Fixes <a class="header-anchor" href="#enhancements-fixes" aria-label="Permalink to &quot;Enhancements &amp; Fixes&quot;">​</a></h2><h3 id="ha-2026-5-2026-6-component-compatibility" tabindex="-1">HA 2026.5 / 2026.6 Component Compatibility <a class="header-anchor" href="#ha-2026-5-2026-6-component-compatibility" aria-label="Permalink to &quot;HA 2026.5 / 2026.6 Component Compatibility&quot;">​</a></h3><p>This release has a large backend update for full HA 2026.5-6+ compatibility.<br> All deprecated components have been removed and use current HA elements (<code>ha-input</code>, <code>ha-icon-button-size</code> variables) across the board. It brings improved UI consistency and a comprehensive standardization of all component styles to use HA&#39;s native CSS variable system. This ensures that LCARdS looks and behaves correctly across all HA themes in both light and dark modes.</p><h3 id="card-suggestion-supoort-in-the-card-picker-ha-2026-6" tabindex="-1">Card Suggestion Supoort in the Card Picker (HA 2026.6+) <a class="header-anchor" href="#card-suggestion-supoort-in-the-card-picker-ha-2026-6" aria-label="Permalink to &quot;Card Suggestion Supoort in the Card Picker (HA 2026.6+)&quot;">​</a></h3><p>LCARdS cards now participate in Home Assistant&#39;s <strong>&quot;Add card by entity&quot;</strong> flow in the card picker when adding a card to a dashboard.</p><img class="release-shot" alt="LCARdS cards offered in the HA card picker" src="`+h+'"><table tabindex="0"><thead><tr><th>Card</th><th>Suggested for</th></tr></thead><tbody><tr><td>Button</td><td>Any entity</td></tr><tr><td>Chart</td><td><code>sensor</code>, <code>input_number</code>, <code>number</code>, <code>weather</code></td></tr><tr><td>Slider</td><td><code>light</code>, <code>fan</code>, <code>cover</code>, <code>input_number</code>, <code>number</code>, <code>climate</code>, <code>media_player</code>, <code>humidifier</code>, <code>water_heater</code>, <code>valve</code></td></tr><tr><td>Select Menu</td><td><code>input_select</code>, <code>select</code></td></tr></tbody></table><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.05.24.1...2026.06.01.1" target="_blank" rel="noreferrer">2026.05.24.1...2026.06.01.1</a></p>',24))])}const f=s(c,[["render",p]]);export{y as __pageData,f as default};
